-- # Lernfeld 5: Cyberphysische Systeme > ## Programmierung > - Programmiersprachen > - Aufbau

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Können alle Programmiersprachen ohne Variablen auskommen?', 2, '[{"text": "Nein", "correct": true, "because": "Variablen sind zentral für Datenverarbeitung"}, {"text": "Ja", "correct": false, "because": "Funktionale Sprachen haben Alternativen, aber selten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Syntax einer Programmiersprache unabhängig von ihrer Semantik?', 2, '[{"text": "Nein", "correct": true, "because": "Syntax bestimmt, wie Semantik ausgedrückt wird"}, {"text": "Ja", "correct": false, "because": "Beides ist verknüpft"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Aufbau einer Programmiersprache ohne Kontrollstrukturen wie Schleifen funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Kontrollstrukturen steuern Ablauf"}, {"text": "Ja", "correct": false, "because": "Wiederholung wäre unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind alle Programmiersprachen gleich im Hinblick auf ihren grundlegenden Aufbau?', 2, '[{"text": "Nein", "correct": true, "because": "Paradigmen und Syntax variieren"}, {"text": "Ja", "correct": false, "because": "Unterschiede sind signifikant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Programmiersprache ohne Funktionen oder Methoden komplexe Programme unterstützen?', 2, '[{"text": "Nein", "correct": true, "because": "Modularität ist für Komplexität essenziell"}, {"text": "Ja", "correct": false, "because": "Ohne Struktur wird es unübersichtlich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Element ist in fast allen Programmiersprachen zentral für die Datenverarbeitung?', 2, '[{"text": "Variablen", "correct": true, "because": "Speichern und manipulieren Daten"}, {"text": "Kommentare", "correct": false, "because": "Nur Dokumentation"}, {"text": "Operatoren", "correct": false, "because": "Wichtig, aber sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur im Aufbau einer Programmiersprache steuert den Programmfluss?', 3, '[{"text": "Kontrollstrukturen", "correct": true, "because": "If, Loops, etc. lenken Ablauf"}, {"text": "Datentypen", "correct": false, "because": "Definieren Daten"}, {"text": "Klassen", "correct": false, "because": "Objektorientiert, nicht allgemein"}]'),
('00000000-0000-0000-0000-000000000000', 'Was beschreibt die Syntax einer Programmiersprache am besten?', 2, '[{"text": "Regeln für gültige Befehle", "correct": true, "because": "Syntax legt Schreibweise fest"}, {"text": "Bedeutung der Befehle", "correct": false, "because": "Das ist Semantik"}, {"text": "Ausführungsgeschwindigkeit", "correct": false, "because": "Leistungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept im Aufbau ermöglicht die Wiederverwendung von Code?', 2, '[{"text": "Funktionen", "correct": true, "because": "Modularität fördert Wiederverwendung"}, {"text": "Schleifen", "correct": false, "because": "Wiederholung, nicht Wiederverwendung"}, {"text": "Variablen", "correct": false, "because": "Speicherung, nicht Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Teil des Aufbaus definiert, welche Werte eine Variable annehmen kann?', 2, '[{"text": "Datentypen", "correct": true, "because": "Bestimmen Typ und Bereich"}, {"text": "Operatoren", "correct": false, "because": "Verarbeiten Werte"}, {"text": "Kommentare", "correct": false, "because": "Nur Erläuterung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind im grundlegenden Aufbau fast aller Programmiersprachen enthalten?', 4, '[{"text": "Variablen", "correct": true, "because": "Datenhaltung essenziell"}, {"text": "Kontrollstrukturen", "correct": true, "because": "Ablaufsteuerung nötig"}, {"text": "Grafische Oberflächen", "correct": false, "because": "Nicht universell"}, {"text": "Operatoren", "correct": true, "because": "Datenmanipulation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente beeinflussen die Semantik einer Programmiersprache?', 3, '[{"text": "Befehlsbedeutung", "correct": true, "because": "Semantik ist Interpretation"}, {"text": "Syntaxregeln", "correct": true, "because": "Struktur trägt zur Bedeutung"}, {"text": "Schriftart", "correct": false, "because": "Irrelevant für Semantik"}, {"text": "Ausführungslogik", "correct": true, "because": "Bestimmt Verhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Kontrollstrukturen gibt es im Aufbau von Programmiersprachen?', 3, '[{"text": "Bedingungen (if)", "correct": true, "because": "Entscheidungsfindung"}, {"text": "Schleifen (loops)", "correct": true, "because": "Wiederholung"}, {"text": "Klassen", "correct": false, "because": "Objektstruktur"}, {"text": "Sprunganweisungen (goto)", "correct": true, "because": "Ablaufsteuerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein modularer Aufbau mit Funktionen?', 4, '[{"text": "Wiederverwendbarkeit", "correct": true, "because": "Code mehrfach nutzbar"}, {"text": "Lesbarkeit", "correct": true, "because": "Struktur klarer"}, {"text": "Hohe Ausführungsgeschwindigkeit", "correct": false, "because": "Nicht primär"}, {"text": "Wartbarkeit", "correct": true, "because": "Änderungen einfacher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile der Syntax sind in Programmiersprachen entscheidend?', 3, '[{"text": "Schlüsselwörter", "correct": true, "because": "Definieren Befehle"}, {"text": "Trennzeichen", "correct": true, "because": "Strukturieren Code"}, {"text": "Farbcodierung", "correct": false, "because": "Editor-Funktion"}, {"text": "Operatoren", "correct": true, "because": "Syntax für Operationen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Jede Programmiersprache hat eine einheitliche Syntax. b) Kontrollstrukturen sind essenziell für Programmfluss.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Syntax variiert, Kontrolle zentral"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Funktionen sind optional im Aufbau moderner Programmiersprachen. b) Variablen ermöglichen dynamische Datenverarbeitung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Funktionen essenziell, Variablen dynamisch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Datentypen sind in allen Programmiersprachen gleich. b) Syntaxfehler verhindern die Ausführung eines Programms.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Datentypen variieren, Syntax kritisch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der Aufbau einer Programmiersprache beeinflusst ihre Lesbarkeit. b) Semantik ist irrelevant für die Programmausführung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aufbau wirkt, Semantik entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Operatoren sind für mathematische Operationen notwendig. b) Jede Programmiersprache benötigt objektorientierte Elemente.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Operatoren essenziell, Objektorientierung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

